        if let session = activeInvokes["control"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildControl.map { !$0.isInFinalState } ?? false
        }
        if let session = activeInvokes["watcher"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildWatcher.map { !$0.isInFinalState } ?? false
        }
        if let session = activeInvokes["worker"], session.sessionID.utf8.elementsEqual(childSessionID.utf8) {
            return sceInvokeChildWorker.map { !$0.isInFinalState } ?? false
        }
        return false
    }

    /// Delivers an event addressed to a child's published location (W3C SCXML C.1).
    /// The parent mints `parentSession.invokeId` for each child and that id is what the
    /// child's `_ioprocessors` entry names, so a `<send>` whose target decodes to one of
    /// them is addressed to that child and not to this machine. False names no live
    /// child of ours, and the event takes the ordinary external path.
    public func deliverToChildSession(childSessionID: String, eventName: String, eventData: String) -> Bool {
        if !isChildSessionRunning(childSessionID) {
            return false
        }
        if let session = activeInvokes["control"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildControl {
            deliverToChild(child, eventName: eventName, eventData: eventData)
            return true
        }
        if let session = activeInvokes["watcher"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildWatcher {
            deliverToChild(child, eventName: eventName, eventData: eventData)
            return true
        }
        if let session = activeInvokes["worker"], session.sessionID.utf8.elementsEqual(childSessionID.utf8),
           let child = sceInvokeChildWorker {
            deliverToChild(child, eventName: eventName, eventData: eventData)
            return true
        }
        return false
    }


    /// Enters one state (W3C SCXML 3.8): adds it to the configuration, runs its
    /// `<onentry>`, and its `<initial>` transition's content when its initial
    /// state is entered by default.
    public func executeEntryActions(_ state: StaticInvokeParamsState, engine: Engine<StaticInvokeParamsPolicy>, isDefaultEntry: Bool) {
        switch state {
        case .plain:
            // W3C SCXML 6.4: an <invoke> starts at the end of the macrostep, so its
            // entry is deferred, and a state that exits before then never starts it.
            do {
                sceInvokeStartsControl += 1
                let generatedInvokeID = "plain.\(sceInvokeStartsControl).control"
                deferInvoke(&pendingInvokes, PendingInvoke(
                    invokeID: generatedInvokeID,
                    state: .plain,
                    documentID: "control"
                ))
            }
            // W3C SCXML 6.4: an <invoke> starts at the end of the macrostep, so its
            // entry is deferred, and a state that exits before then never starts it.
            do {
                sceInvokeStartsWatcher += 1
                let generatedInvokeID = "plain.\(sceInvokeStartsWatcher).watcher"
                deferInvoke(&pendingInvokes, PendingInvoke(
                    invokeID: generatedInvokeID,
                    state: .plain,
                    documentID: "watcher"
                ))
            }
        case .working:
            // W3C SCXML 3.8 + 4.9: onentry block 0; an error ends it.
            sceBlock: do {


                if ({ () -> Bool in let sceFailure = Failure(); let sceValue: UInt32 = Checked.add(sceFailure, self.vBase, 3); if sceFailure.failed { engine.raise(EventWithMetadata.platformError(StaticInvokeParamsEvent.errorExecution, message: "<assign location='base'>: an integer operation overflowed or failed")); return true }; self.vBase = sceValue; return false }()) {
                    break sceBlock  // W3C SCXML 4.9: the error ends the block
                }

            }
            // W3C SCXML 6.4: an <invoke> starts at the end of the macrostep, so its
            // entry is deferred, and a state that exits before then never starts it.
            do {
                sceInvokeStartsWorker += 1
                let generatedInvokeID = "working.\(sceInvokeStartsWorker).worker"
                deferInvoke(&pendingInvokes, PendingInvoke(
                    invokeID: generatedInvokeID,
                    state: .working,
                    documentID: "worker"
