    /// Exits one state (W3C SCXML 3.9): records its histories, runs its `<onexit>`,
    /// cancels its invocations and removes it from the configuration, in
    /// §scxml-D-exitStates's order.
    public func executeExitActions(_ state: StaticInvokeParamsState, engine: Engine<StaticInvokeParamsPolicy>, configurationBeforeExit: [StaticInvokeParamsState]) {
        // §scxml-D-exitStates orders one state's exit as onexit, then cancelInvoke,
        // then configuration.delete(s), so `In(s)` inside s's own handler is true:
        // the <onexit> switch comes first and the removal from the configuration
        // last.
        switch state {
        default:
            break  // No exit actions
        }
        // W3C SCXML 6.4: the invocations of an exited state end with it: one not yet
        // started never starts, and a running session is exited, its states' <onexit>
        // run, before it is dropped. What that exit sends to #_parent is dropped with
        // it (test252).
        switch state {
        case .plain:
            cancelInvokesForState(&pendingInvokes, .plain)
            sceInvokeChildControl?.stop()
            sceInvokeChildControl = nil
            activeInvokes["control"] = nil
            sceInvokeDoneControl = false
            sceInvokeChildWatcher?.stop()
            sceInvokeChildWatcher = nil
            activeInvokes["watcher"] = nil
            sceInvokeDoneWatcher = false
        case .working:
            cancelInvokesForState(&pendingInvokes, .working)
            sceInvokeChildWorker?.stop()
            sceInvokeChildWorker = nil
            activeInvokes["worker"] = nil
            sceInvokeDoneWorker = false
        default:
            break  // No invocations to cancel
        }
    }



    /// Appendix D selectTransitions, the half only this document can answer: the
    /// first of `state`'s own transitions, in document order, that `event` enables
    /// and whose guard holds. The engine walks the atomic states and their
    /// ancestors and keeps the ordered set; the null event asks for eventless
    /// transitions.
    public func firstEnabledTransition(
        _ state: StaticInvokeParamsState,
        event: StaticInvokeParamsEvent,
        engine: Engine<StaticInvokeParamsPolicy>
    ) -> EnabledTransition<StaticInvokeParamsState>? {
        switch state {
        case .plain:
            if event == .doneInvokeControl {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 0,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
            if event == .bump {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 1,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
            if event == .doneInvokeWatcher {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [],
                        transitionIndex: 2,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
        case .working:
            if event == .doneInvokeWorker {
                do {
                    return EnabledTransition(
                        source: state,
                        targets: [.state(.plain)],
                        transitionIndex: 0,
                        hasActions: true,
                        isInternal: false
                    )
                }
            }
        default:
            break
        }
        return nil
    }

